AUTH_NAME = #{authName}, AUTH_DESC = #{authDesc}, AUTH_TYPE = #{authType}, FSTG_MENU_NO = #{fstgMenuNo}, USE_YN = #{useYn}, UPD_DT = SYSTIMESTAMP
WHERE AUTH_CODE = #{authCode}

